//! Replays `oracle/unit/structure.py`: the `plumber_doc` traces of the
//! adversarial corpus `adv-structure` (its depth windows also from one and
//! two frames deeper) and of the files of `quick` that have a structure
//! tree, metadata containers or annotations, the `plumber_objects` traces
//! of its annotation cases (given their Python trace as the oracle input),
//! and `bytes.decode("utf-8")` / `bytes.decode("utf-16")`
//! (`pycompat::codecs`) on generated byte strings.
//!
//! What it checks: `pdfplumber::structure`, the metadata of
//! `pdfplumber::pdf` (`read_metadata`, `resolve_and_decode` in place),
//! `Page.annots`/`hyperlinks`, `pdfplumber::utils::pdfinternals`
//! (`decode_text`), `pycompat::codecs`, and the stage runner.
//!
//! `STRUCTURE_ONLY=<substring>[,<substring>...]` restricts the traces to
//! the file names containing one of them.

use std::fs;
use std::sync::Arc;

use pdfminer::cmapdb::{CMapDB, DirCMapProvider};
use pdftrace::stages::common::with_stage_entry;
use pdftrace::stages::py_process::{self, PyProcess};
use pdftrace::stages::{self, StageInput};
use pdftrace::typed_json::{self, Json};
use pdftrace::unit::{cache_dir, UnitData};
use pdftrace::value::Value;
use pycompat::codecs::{decode_utf16, decode_utf8};
use pycompat::recursion::{Depth, C_RECURSION_LIMIT};
use pycompat::PyResult;

/// Opens the data and installs the provider of the predefined CMaps.
fn open() -> UnitData {
    let data = UnitData::open("structure");
    let meta = fs::read_to_string(data.path("meta.json")).expect("meta.json");
    let meta = typed_json::parse_json(&meta).expect("meta.json is JSON");
    let Some(Json::String(rel)) = meta.get("cmap_dir") else { panic!("meta.json has no cmap_dir") };
    let dir = cache_dir().join(rel);
    let provider = DirCMapProvider::new(&dir).unwrap_or_else(|e| panic!("{}: {e}", dir.display()));
    CMapDB::set_default_provider(Some(Arc::new(provider)));
    data
}

fn generator_process(data: &UnitData) -> PyProcess {
    let cases = data.cases("py_process");
    let [(_, state)] = &cases[..] else { panic!("one process state") };
    PyProcess::from_value(state)
}

/// The `{"py": .., "c_left": ..}` depth of a case.
fn depth(v: &Value) -> Depth {
    let Value::Dict(items) = v else { panic!("a depth: {v:?}") };
    let field = |name: &str| {
        let v = items.iter().find(|(k, _)| k.as_str() == Some(name)).map(|(_, v)| v).expect("a depth field");
        let Value::Int(i) = v else { panic!("an int: {v:?}") };
        u32::try_from(i.as_i64().expect("small")).expect("a depth")
    };
    Depth { py: field("py"), c: C_RECURSION_LIMIT - field("c_left") }
}

fn first_difference(expected: &str, got: &str) -> String {
    for (i, (e, g)) in expected.lines().zip(got.lines()).enumerate() {
        if e != g {
            return format!("line {}:\n  oracle: {}\n  rust:   {}", i + 1, clip(e), clip(g));
        }
    }
    format!("line counts {} (oracle) and {} (rust)", expected.lines().count(), got.lines().count())
}

fn clip(s: &str) -> &str {
    let mut end = s.len().min(400);
    while !s.is_char_boundary(end) {
        end -= 1;
    }
    &s[..end]
}

#[test]
fn stage_traces() {
    let data = open();
    py_process::set(generator_process(&data));
    let only = std::env::var("STRUCTURE_ONLY").ok();
    let mut failures = Vec::new();
    let (mut n, mut depth_cases, mut deeper_entries, mut objects) = (0, 0, 0, 0);
    for (args, expected) in data.cases("stages") {
        let [Value::Str(name), Value::Bytes(pdf), password, Value::Str(what), Value::Int(max_pages), entry] = &args[..]
        else {
            panic!("bad case {args:?}");
        };
        let name = name.as_str().expect("a file name");
        if only.as_ref().is_some_and(|o| !o.split(',').any(|s| name.contains(s))) {
            continue;
        }
        let password_given = matches!(password, Value::Str(_));
        let password = match password {
            Value::Str(p) => p.as_str().expect("a password").to_owned(),
            _ => String::new(),
        };
        let max_pages = max_pages.as_i64().filter(|&m| m > 0).map(|m| m as usize);
        let what = what.as_str().expect("a stage");
        let Value::Str(expected) = &expected else { panic!("bad output") };
        let expected = expected.as_str().expect("ASCII");
        let stage = stages::lookup(what).expect("a stage");
        let input = StageInput {
            pdf,
            password: &password,
            password_given,
            max_pages,
            oracle: stage.oracle_input.then_some(expected),
        };
        let run = stage.run.expect("an implemented stage");
        let mut out = Vec::new();
        match entry {
            Value::None => run(&input, &mut out).expect("write to memory"),
            entry => {
                deeper_entries += 1;
                with_stage_entry(depth(entry), || run(&input, &mut out)).expect("write to memory")
            }
        }
        let got = String::from_utf8(out).expect("ASCII");
        n += 1;
        if what == "plumber_objects" {
            objects += 1;
        }
        if expected.contains("RecursionError") {
            depth_cases += 1;
        }
        if got != expected {
            failures.push(format!("{name} [{what}]: {}", first_difference(expected, &got)));
        }
    }
    if only.is_none() {
        assert!(n > 450, "only {n} traces");
        assert!(objects > 40, "only {objects} plumber_objects traces");
        assert!(depth_cases > 80, "only {depth_cases} traces reach the recursion limit");
        assert!(deeper_entries > 100, "only {deeper_entries} traces from a deeper entry");
    }
    assert!(
        failures.is_empty(),
        "{} of {n} traces differ:\n{}",
        failures.len(),
        failures[..failures.len().min(20)].join("\n")
    );
}

/// A PDF of one page whose structure elements are `elems` (objects 11..),
/// under the root 10 (`/K [11 0 R]`), with the parent tree `parents` (the
/// page's `/StructParents 0`). Written here: Python never returns on the
/// cycles these tests build, so there is no oracle trace to replay.
fn tagged_pdf(elems: &[(u32, &str)], parents: &str) -> Vec<u8> {
    let mut objects: Vec<(u32, String)> = vec![
        (1, "<< /Type /Catalog /Pages 2 0 R /StructTreeRoot 10 0 R >>".into()),
        (2, "<< /Type /Pages /Kids [3 0 R] /Count 1 >>".into()),
        (3, "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 100 100] /Contents 4 0 R /StructParents 0 >>".into()),
        (4, "<< /Length 23 >>\nstream\n/P <</MCID 0>> BDC EMC\nendstream".into()),
        (10, "<< /Type /StructTreeRoot /K [11 0 R] /ParentTree 20 0 R >>".into()),
        (20, format!("<< /Nums [0 [{parents}]] >>")),
    ];
    objects.extend(elems.iter().map(|(n, body)| (*n, (*body).to_owned())));
    objects.sort_by_key(|(n, _)| *n);
    let mut out = b"%PDF-1.7\n".to_vec();
    let mut offsets = Vec::new();
    for (n, body) in &objects {
        offsets.push((*n, out.len()));
        out.extend_from_slice(format!("{n} 0 obj\n{body}\nendobj\n").as_bytes());
    }
    let size = objects.last().map_or(0, |(n, _)| n + 1);
    let xref = out.len();
    out.extend_from_slice(format!("xref\n0 {size}\n").as_bytes());
    for n in 0..size {
        match offsets.iter().find(|(m, _)| *m == n) {
            Some((_, pos)) => out.extend_from_slice(format!("{pos:010} 00000 n \n").as_bytes()),
            None => out.extend_from_slice(b"0000000000 65535 f \n"),
        }
    }
    out.extend_from_slice(format!("trailer\n<< /Size {size} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n").as_bytes());
    out
}

/// `page.structure_tree` of the first page of `pdf`.
fn page_tree(pdf: Vec<u8>) -> PyResult<Vec<pdfplumber::obj::PyValue>> {
    use pdfplumber::pdf::{OpenOptions, Source, PDF};
    let source = Source::Stream { data: pdf.into(), kind: pdfminer::pdfparser::FileKind::BytesIO };
    let pdf = PDF::open(source, OpenOptions::new())?;
    let pages = pdf.pages()?;
    pages[0].structure_tree()
}

/// A cycle among the elements a page's parent tree reaches: Python's
/// `_resolve_children` loops for ever; the port raises `MemoryError` once
/// every element was processed (`pdfplumber::structure`, "Not modeled").
#[test]
fn page_scope_cycles_raise_memory_error() {
    let cases: [(&str, &[(u32, &str)], &str); 3] = [
        // the element's parent among its children
        (
            "parent",
            &[(11, "<< /S /Document /P 10 0 R /K [12 0 R] >>"), (12, "<< /S /P /P 11 0 R /K [0 11 0 R] >>")],
            "12 0 R",
        ),
        // itself among its children
        ("self", &[(11, "<< /S /Document /P 10 0 R /K [11 0 R 0] >>")], "11 0 R"),
        // a longer cycle, reached through an element seen twice
        (
            "long",
            &[
                (11, "<< /S /Document /P 10 0 R /K [12 0 R 12 0 R] >>"),
                (12, "<< /S /Div /P 11 0 R /K [13 0 R] >>"),
                (13, "<< /S /P /P 12 0 R /K [0 14 0 R] >>"),
                (14, "<< /S /Span /P 13 0 R /K [12 0 R] >>"),
            ],
            "14 0 R",
        ),
    ];
    for (name, elems, parents) in cases {
        let err = page_tree(tagged_pdf(elems, parents)).expect_err(name);
        assert_eq!(err.kind, pycompat::ExcKind::MemoryError, "{name}: {err:?}");
    }
}

/// Without a cycle the walk ends however often it reaches an element (a
/// DAG's elements are processed once per path), and an element that
/// raises is reached before the walk repeats itself: the guard never
/// fires there.
#[test]
fn page_scope_dags_end() {
    let dag = tagged_pdf(
        &[
            (11, "<< /S /Document /P 10 0 R /K [12 0 R 13 0 R 12 0 R] >>"),
            (12, "<< /S /Div /P 11 0 R /K [14 0 R 14 0 R] >>"),
            (13, "<< /S /Div /P 11 0 R /K [14 0 R] >>"),
            (14, "<< /S /P /P 12 0 R /K [0] >>"),
        ],
        "14 0 R 13 0 R",
    );
    let tree = page_tree(dag).expect("a DAG's tree");
    assert_eq!(tree.len(), 1);
    // a cycle, and an element whose children cannot be iterated: its
    // PDFKeyError comes first
    let failing = tagged_pdf(
        &[
            (11, "<< /S /Document /P 10 0 R /K [12 0 R 15 0 R] >>"),
            (12, "<< /S /P /P 11 0 R /K [0 11 0 R] >>"),
            (15, "<< /S /Span /P 11 0 R /K 16 0 R >>"),
            (16, "<< /Length 1 >>\nstream\nx\nendstream"),
        ],
        "12 0 R 15 0 R",
    );
    let err = page_tree(failing).expect_err("the stream's error");
    assert_eq!(err.kind, pycompat::ExcKind::PDFKeyError, "{err:?}");
}

/// The value of a decoding: the text, or the exception.
fn outcome(r: PyResult<pycompat::PyStr>) -> Value {
    match r {
        Ok(text) => Value::py_str(&text),
        Err(e) => Value::Exception { class: e.kind.name().to_owned(), message: (&e.py_message()).into() },
    }
}

#[test]
fn codecs() {
    let data = open();
    let cases = data.cases("codecs");
    assert!(cases.len() > 3000, "only {} cases", cases.len());
    let mut failures = Vec::new();
    for (args, expected) in &cases {
        let [Value::Bytes(b)] = &args[..] else { panic!("bad case {args:?}") };
        let got = Value::List(vec![outcome(decode_utf8(b)), outcome(decode_utf16(b))]);
        if !got.same(expected) {
            failures.push(format!("{b:02x?}: expected {expected:?}, got {got:?}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} differ:\n{}",
        failures.len(),
        cases.len(),
        failures[..failures.len().min(20)].join("\n")
    );
}
